ALTER TABLE t20 PLACEMENT POLICY=p_missing;
CREATE TABLE t20_new (id INT) PARTITION BY RANGE(id) (
  PARTITION p0 VALUES LESS THAN (100) PLACEMENT POLICY=p20,
  PARTITION p1 VALUES LESS THAN (200) PLACEMENT POLICY=p_missing
);
ALTER TABLE t20 ADD PARTITION (
  PARTITION p5 VALUES LESS THAN (500) PLACEMENT POLICY=p_missing
);
ALTER TABLE t20 REORGANIZE PARTITION p0 INTO (
  PARTITION p00 VALUES LESS THAN (50) PLACEMENT POLICY=p20,
  PARTITION p01 VALUES LESS THAN (100) PLACEMENT POLICY=p_missing
);
